class Solution:
    def removeAlmostEqualCharacters(self, word):
        w = list(word); ans = 0
        for i in range(1, len(w)):
            if abs(ord(w[i]) - ord(w[i - 1])) <= 1:
                ans += 1
                nxt = w[i + 1] if i + 1 < len(w) else ''
                for c in map(chr, range(97, 123)):
                    if abs(ord(c) - ord(w[i - 1])) > 1 and (not nxt or abs(ord(c) - ord(nxt)) > 1):
                        w[i] = c
                        break
        return ans

