class Solution {
public:
    int removeAlmostEqualCharacters(string word) {
        int ans = 0;
        for (int i = 1; i < (int)word.size(); i++) {
            if (abs(word[i] - word[i - 1]) <= 1) {
                ans++;
                char nxt = i + 1 < (int)word.size() ? word[i + 1] : 0;
                for (char c = 'a'; c <= 'z'; c++)
                    if (abs(c - word[i - 1]) > 1 && (!nxt || abs(c - nxt) > 1)) { word[i] = c; break; }
            }
        }
        return ans;
    }
};

