class Solution {
    public int removeAlmostEqualCharacters(String word) {
        char[] w = word.toCharArray(); int ans = 0;
        for (int i = 1; i < w.length; i++) {
            if (Math.abs(w[i] - w[i - 1]) <= 1) {
                ans++;
                char nxt = i + 1 < w.length ? w[i + 1] : 0;
                for (char c = 'a'; c <= 'z'; c++)
                    if (Math.abs(c - w[i - 1]) > 1 && (nxt == 0 || Math.abs(c - nxt) > 1)) { w[i] = c; break; }
            }
        }
        return ans;
    }
}

