var removeAlmostEqualCharacters = function(word) {
    const w = word.split(''); let ans = 0;
    for (let i = 1; i < w.length; i++) {
        if (Math.abs(w.charCodeAt(i) - w.charCodeAt(i - 1)) <= 1) {
            ans++;
            const nxt = i + 1 < w.length ? w.charCodeAt(i + 1) : 0;
            for (let c = 97; c <= 122; c++)
                if (Math.abs(c - w.charCodeAt(i - 1)) > 1 && (!nxt || Math.abs(c - nxt) > 1)) { w[i] = String.fromCharCode(c); break; }
        }
    }
    return ans;
};

